    [listed in matrix] -> user "Request Approval from Designated Approvers"
    [not listed in matrix] -> user "Request Review from Sr. Manager, Deal Desk"
  } ->
    user "Add Pending Approval Label to Issue" #t04 ->
    and "Fork Approval Processes" {
    user "Review Issue" #t05 (lane="Deal Desk") -> xor "Will it Negatively Impact Quoting Cycle?" {
    [negatively impacts] -> user "Add Need More Information Label" (lane="Deal Desk") -> user "Partner with DRI to Identify Alternative Solutions" -> #t05
    [does not negatively impact] -> user "Secure Approval in Comments" (lane="Deal Desk") -> user "Add Deal Desk Approved Label" (lane="Deal Desk") -> xor "Is the Proposed Change Approved?" #g04 {
    [approved] -> user "Add Approved Label" (lane="Systems") -> service "Move Forward with Work" (lane="Systems") -> end "End Approved" (lane="Systems")
    [rejected] -> user "Add Rejected Label and Present Alternative Solution" (lane="Systems") -> end "End Rejected" (lane="Systems")
  }
  };
    user "Review Issue" #t10 (lane="Channel Operations") -> xor "Will it Negatively Impact Channel Priorities?" {
    [negatively impacts] -> user "Add Need More Information Label" (lane="Channel Operations") -> user "Partner with DRI to Identify Alternative Solutions" -> #t10
    [does not negatively impact] -> user "Secure Approval in Comments" (lane="Channel Operations") -> user "Add Channel Ops Approved Label" (lane="Channel Operations") -> #g04
  }
  }
  }
}

