process "Field Deprecation" {
  @lane "Responsible" {
    start "Start" ->
    user "Open issue listing fields to deprecate" ->
    user "Add technical debt label to issue" ->
    and "Fork Alerts" {
    send "Alert Data Team";
    send "Alert Partner Teams"
  } ->
    user "Prepend [DEPRECATE] or [DELETE] to field name" #t05 ->
    xor "Can field name accommodate text?" {
    [can accommodate] -> user "Prepend [DEPRECATE]"
    [cannot accommodate] -> user "Copy name to description, trim, and try again or use [DELETE]"
  } ->
    user "Pull from master and scan for API name" #t08 ->
    xor "Is field used in code base?" {
    [used in code] -> user "Investigate if code can be updated"
    [not used in code] -> ()
  } ->
    user "Proceed with deprecation" #t10 ->
    xor "Is sandbox out of date?" {
    [out of date] -> user "Refresh sandbox with Systems Team" (lane="Systems Team")
    [not out of date] -> ()
  } ->
    user "Push updated code to sandbox and start change set" #t12 ->
    user "Log into sandbox and attempt to delete fields" ->
    user "Record field connections" ->
    user "Investigate connections and determine if field can be deleted" ->
    xor "Can field be deleted in sandbox?" {
    [can be deleted] -> user "List deletable fields on final comment" -> user "Update due date of issue to deletion date" -> user "Confirm no issues with tagged related teams" -> user "Validate change sets with updated automations" -> user "Deploy change sets and delete fields from production" -> catch:none "Wait 1 day lag time" -> user "Delete fields from Deleted Fields section in Salesforce" -> end "End Deleted"
    [cannot be deleted] -> user "Link investigation issue to field and assign owner" -> end "End Not Deleted"
  }
  }
}

process "Salesforce Deployment and Change Control Process" {
  @lane "Developers and Administrators" {
    start "Start" ->
    user "Proceed Through Pipeline" ->
    user "Link Merge Request to Issue" ->
    xor "MR Contains Apex Code, Triggers, or Visualforce Pages?" {
    [contains Apex Code, Triggers, or Visualforce Pages] -> user "Approve Merge Request" (lane="Salesforce Engineer")
    [does not contain Apex Code, Triggers, or Visualforce Pages] -> ()
  }
  }
  @lane "Business DRI" {
    -> user "Complete User Acceptance Testing and Sign-off" #t04
  }
  @lane "Business Program Owner" {
    -> user "Business Program Owner Sign-off"
  }
  @lane "Systems Owner" {
    -> user "Systems Owner Sign-off"
  }
  @lane "Salesforce Release Management" {
    -> xor "Is Destructive Field Change?" {
    [is destructive field change] -> and "Fork: Field Impact Analysis" {
    user "Identify Field Impact and Usage" (lane="CRM Systems Team");
    user "Verify Field Not in Snowflake Tables" (lane="Data Team")
  } -> xor "Field Change Acceptable?" #g03 {
    [field change is acceptable] -> service "Remove Field via Gearset"
    [field change is not acceptable] -> user "Mark Field as Deprecated"
  }
    [not a destructive field change] -> ()
  } ->
    xor "Is Destructive Code Change?" #g04 {
    [is destructive code change] -> user "Sign-off Destructive Code Change" (lane="Senior Director of CRM Systems") -> service "Complete Removal via Gearset Pipeline"
    [not a destructive code change] -> ()
  } ->
    xor "Related to Opportunity.Net_ARR__c?" #g05 {
    [related to Opportunity.Net_ARR__c] -> user "Approve Critical Field Change" (lane="Senior Director of Sales Systems")
    [not related to Opportunity.Net_ARR__c] -> ()
  } ->
    xor "Non-Standard Scenario?" #g06 {
    [is non-standard scenario] -> user "Approve Non-Standard Scenario" (lane="Senior Director of Sales Systems") -> user "Flag as CMT: Emergency Change"
    [is standard scenario] -> ()
  } ->
    user "Validate Issue Sign-offs, CAB Approval, and Conflicts" #t16 ->
    service "Approve and Deploy Changes via Gearset"
  }
  @lane "Developers and Administrators" {
    -> user "Provide Post-Deployment Screenshots and Review Changes" ->
    end "End - Deployment Complete"
  }
}

